(()=>{class t extends HTMLElement{connectedCallback(){this.tabs=this.querySelectorAll("[data-tab]"),this.contents=this.querySelectorAll("[data-content]"),this.tabs.forEach(t=>{t.addEventListener("click",()=>this.switchTab(t))})}switchTab(t){const s=t.dataset.tab;this.tabs.forEach(t=>t.classList.remove("is-active")),t.classList.add("is-active"),this.contents.forEach(t=>t.classList.remove("is-active")),this.querySelector(`[data-content="${s}"]`)?.classList.add("is-active")}}customElements.define("simple-tabs",t)})();